CREATE TABLE public.commercial_operations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opportunity_id uuid NOT NULL UNIQUE REFERENCES public.opportunities(id) ON DELETE CASCADE, listing_id uuid NOT NULL REFERENCES public.listings(id), seller_company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, buyer_company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, code text NOT NULL, version integer NOT NULL DEFAULT 1, terms jsonb NOT NULL, seller_accepted_by uuid, seller_accepted_at timestamptz, buyer_accepted_by uuid, buyer_accepted_at timestamptz, confirmed_at timestamptz, status text NOT NULL DEFAULT 'agreement_declared', reserved_kg numeric NOT NULL DEFAULT 0 CHECK(reserved_kg>=0), delivered_kg numeric NOT NULL DEFAULT 0 CHECK(delivered_kg>=0), released_kg numeric NOT NULL DEFAULT 0, dispute_open boolean NOT NULL DEFAULT false, payment_status text NOT NULL DEFAULT 'not_declared', payment_evidence text, commission_rate numeric NOT NULL DEFAULT 0.005, commission_enabled boolean NOT NULL DEFAULT true, commission_payer text NOT NULL DEFAULT 'seller', commission_amount numeric NOT NULL DEFAULT 0, commission_status text NOT NULL DEFAULT 'estimated', commission_evidence text, required_documents text[] NOT NULL DEFAULT '{}', reservation_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.commercial_operations TO authenticated; GRANT ALL ON public.commercial_operations TO service_role;
ALTER TABLE public.commercial_operations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "participants read operations" ON public.commercial_operations FOR SELECT TO authenticated USING(public.is_company_member(seller_company_id) OR public.is_company_member(buyer_company_id) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.operation_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_id uuid NOT NULL REFERENCES public.commercial_operations(id) ON DELETE CASCADE, version integer NOT NULL, terms jsonb NOT NULL, seller_by uuid NOT NULL, seller_at timestamptz NOT NULL DEFAULT now(), buyer_by uuid, buyer_at timestamptz, UNIQUE(operation_id,version));
GRANT SELECT ON public.operation_versions TO authenticated; GRANT ALL ON public.operation_versions TO service_role;
ALTER TABLE public.operation_versions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.operation_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_id uuid NOT NULL REFERENCES public.commercial_operations(id) ON DELETE CASCADE, event text NOT NULL, actor uuid NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.operation_events TO authenticated; GRANT ALL ON public.operation_events TO service_role;
ALTER TABLE public.operation_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.operation_deliveries (id uuid PRIMARY KEY, operation_id uuid NOT NULL REFERENCES public.commercial_operations(id) ON DELETE CASCADE, quantity_kg numeric NOT NULL CHECK(quantity_kg>0), note text NOT NULL DEFAULT '', registered_by uuid NOT NULL, registered_at timestamptz NOT NULL DEFAULT now(), accepted_by uuid, accepted_at timestamptz);
GRANT SELECT ON public.operation_deliveries TO authenticated; GRANT ALL ON public.operation_deliveries TO service_role;
ALTER TABLE public.operation_deliveries ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.operation_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_id uuid NOT NULL REFERENCES public.commercial_operations(id) ON DELETE CASCADE, kind text NOT NULL, path text UNIQUE, file_name text NOT NULL, uploaded_by uuid NOT NULL, absence_reason text, waiver_approved_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.operation_documents TO authenticated; GRANT ALL ON public.operation_documents TO service_role;
ALTER TABLE public.operation_documents ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.operation_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation_id uuid NOT NULL REFERENCES public.commercial_operations(id) ON DELETE CASCADE, company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, event text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
GRANT SELECT ON public.operation_notifications TO authenticated; GRANT ALL ON public.operation_notifications TO service_role;
ALTER TABLE public.operation_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members read notifications" ON public.operation_notifications FOR SELECT TO authenticated USING(public.is_company_member(company_id));
CREATE TABLE public.commercial_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), commission_enabled boolean NOT NULL DEFAULT true, commission_rate numeric NOT NULL DEFAULT 0.005 CHECK(commission_rate>=0 AND commission_rate<=1), commission_payer text NOT NULL DEFAULT 'seller' CHECK(commission_payer IN ('seller','buyer')), reservation_days integer NOT NULL DEFAULT 30 CHECK(reservation_days>0));
GRANT SELECT ON public.commercial_settings TO authenticated; GRANT ALL ON public.commercial_settings TO service_role;
ALTER TABLE public.commercial_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "signed in settings" ON public.commercial_settings FOR SELECT TO authenticated USING(true);
CREATE TABLE public.operation_document_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_type public.product_type NOT NULL, modality text NOT NULL, required_kinds text[] NOT NULL DEFAULT '{}', UNIQUE(product_type,modality));
GRANT SELECT ON public.operation_document_rules TO authenticated; GRANT ALL ON public.operation_document_rules TO service_role;
ALTER TABLE public.operation_document_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "signed in document rules" ON public.operation_document_rules FOR SELECT TO authenticated USING(true);
CREATE FUNCTION public.can_read_operation(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.commercial_operations o WHERE o.id=_id AND (public.is_company_member(o.seller_company_id) OR public.is_company_member(o.buyer_company_id) OR public.has_role(auth.uid(),'admin'))) $$;
CREATE POLICY "participants read versions" ON public.operation_versions FOR SELECT TO authenticated USING(public.can_read_operation(operation_id));
CREATE POLICY "participants read events" ON public.operation_events FOR SELECT TO authenticated USING(public.can_read_operation(operation_id));
CREATE POLICY "participants read deliveries" ON public.operation_deliveries FOR SELECT TO authenticated USING(public.can_read_operation(operation_id));
CREATE POLICY "participants read documents" ON public.operation_documents FOR SELECT TO authenticated USING(public.can_read_operation(operation_id));
CREATE POLICY "participants read operation files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='operation-docs' AND EXISTS(SELECT 1 FROM public.operation_documents d WHERE d.path=name AND public.can_read_operation(d.operation_id)));
CREATE POLICY "operators upload operation files" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='operation-docs' AND EXISTS(SELECT 1 FROM public.commercial_operations o WHERE o.id::text=(storage.foldername(name))[2] AND ((o.seller_company_id::text=(storage.foldername(name))[1] AND public.is_company_member(o.seller_company_id,'operator')) OR (o.buyer_company_id::text=(storage.foldername(name))[1] AND public.is_company_member(o.buyer_company_id,'operator')))));
CREATE FUNCTION public.guard_allocated_stock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.reserved_kg < coalesce((SELECT sum(reserved_kg) FROM public.commercial_operations WHERE listing_id=new.id),0) THEN RAISE EXCEPTION 'La reserva pertenece a acuerdos: gestioná desde la operación'; END IF; RETURN new; END $$;
CREATE TRIGGER protect_operation_reservations BEFORE UPDATE ON public.listings FOR EACH ROW EXECUTE FUNCTION public.guard_allocated_stock();
CREATE FUNCTION public.operation_net_value(_kg numeric,_terms jsonb) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE factor numeric; BEGIN factor := CASE _terms->>'price_unit' WHEN 'kg' THEN 1 WHEN 'qq' THEN 100 WHEN 't' THEN 1000 WHEN 'bolsa' THEN (_terms->>'unit_weight_kg')::numeric WHEN 'big_bag' THEN (_terms->>'unit_weight_kg')::numeric ELSE NULL END; IF factor IS NULL OR factor<=0 THEN RAISE EXCEPTION 'Unidad de precio o peso inválido'; END IF; RETURN round(_kg/factor*(_terms->>'price')::numeric,2); END $$;